<script>
(()=>{
  if(window.__giftchetaCardVariantPicker)return;window.__giftchetaCardVariantPicker=true;
  const money=new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'});
  function update(form){
    let combinations=[];try{combinations=JSON.parse(form.dataset.variantCombinations||'[]')}catch{return}
    let defaultOther={};try{defaultOther=JSON.parse(form.dataset.defaultOther||'{}')}catch{}
    combinations=combinations.filter(combo=>Object.entries(defaultOther).every(([key,value])=>combo.other?.[key]===value));
    const groups=[...form.querySelectorAll('[data-card-variant-choice]')].reduce((all,input)=>{const dimension=input.dataset.cardVariantChoice;(all[dimension]??=[]).push(input);return all},{ });
    const selected=()=>Object.fromEntries(Object.entries(groups).map(([dimension,inputs])=>[dimension,inputs.find(input=>input.checked&&!input.disabled)?.value||'']));
    let values=selected();
    for(const [dimension,inputs] of Object.entries(groups)){
      const other=dimension==='color'?'size':'color';
      for(const input of inputs)input.disabled=!combinations.some(combo=>combo[dimension]===input.value&&(!values[other]||combo[other]===values[other]));
      if(!inputs.some(input=>input.checked&&!input.disabled)){const first=inputs.find(input=>!input.disabled);if(first)first.checked=true;}
      values=selected();
    }
    const match=combinations.find(combo=>(!values.color||combo.color===values.color)&&(!values.size||combo.size===values.size));
    const variantId=form.querySelector('[data-card-variant-id]'),button=form.querySelector('button[type="submit"]'),feedback=form.querySelector('.product-card-add-feedback');
    if(variantId)variantId.value=match?String(match.id):'';if(button)button.disabled=!match;
    if(feedback&&!match){feedback.textContent='Тази комбинация не е налична.';feedback.hidden=false}else if(feedback){feedback.hidden=true;feedback.textContent=''}
    if(match){const current=form.closest('.product-card')?.querySelector('[data-card-price-current]'),was=form.closest('.product-card')?.querySelector('[data-card-price-was]');if(current)current.textContent=money.format(Number(match.price));if(was){const discounted=Number(match.regular_price)>Number(match.price);was.hidden=!discounted;if(discounted)was.textContent=money.format(Number(match.regular_price))}}
  }
  document.querySelectorAll('[data-card-variant-form]').forEach(update);
  document.addEventListener('change',event=>{const form=event.target.closest('[data-card-variant-form]');if(form&&event.target.matches('[data-card-variant-choice]'))update(form)});
})();
</script>
<style>
.quick-view-dialog{width:min(940px,calc(100vw - 32px));max-width:none;max-height:calc(100dvh - 32px);padding:0;overflow:auto;border:1px solid #ead9dd;border-radius:20px;background:#fff;box-shadow:0 24px 90px #24121955}.quick-view-dialog::backdrop{background:#21161bd1;backdrop-filter:blur(5px)}.quick-view-shell{position:relative;padding:25px}.quick-view-close{position:absolute;z-index:5;top:12px;right:12px;display:grid;width:42px;height:42px;place-items:center;padding:0;border:1px solid #ead9dd;border-radius:9px;background:#fff;color:#5b4a4d;font-size:1.6rem;line-height:1;cursor:pointer}.quick-view-close:hover{background:#fff4f6;color:var(--accent-dark)}.quick-view-content{padding-top:22px}.quick-view-product-card{display:grid;grid-template-columns:minmax(260px,42%) minmax(0,1fr);align-items:start;overflow:visible;border:0;border-radius:0}.quick-view-product-card .product-card-media{height:min(58vh,460px);min-height:280px;border-radius:14px}.quick-view-product-card .product-card-media>a,.quick-view-product-card .product-card-media>a>img,.quick-view-product-card .product-card-media>a>.image-placeholder{height:100%;aspect-ratio:auto}.quick-view-product-card .product-card-media>a>img{object-fit:contain;background:#fff7f9}.quick-view-product-card .product-card-body{align-self:start;padding:8px 8px 18px 25px;gap:12px}.quick-view-product-card .product-card-detail-meta{display:block}.quick-view-product-card .product-card-short-description{margin:0;color:var(--muted);line-height:1.7}.quick-view-product-card .product-card-sku,.quick-view-product-card .product-card-stock{margin:0;color:var(--muted);font-size:.92rem}.quick-view-product-card .product-card-stock.is-available{color:#26704e}.quick-view-product-card .product-card-stock.is-unavailable{color:#a34747}.quick-view-product-card .product-card-price-row{margin-top:0}.quick-view-product-card .product-card-actions{display:flex;flex-direction:column;align-items:flex-start;gap:10px;margin-top:0;padding-top:0}.quick-view-product-card .product-card-add-form{width:100%}.quick-view-product-card .product-card-add-button,.quick-view-product-card .product-card-options-link{width:auto;min-width:210px}.quick-view-product-card .product-card-quick-preview{display:none}
@media(max-width:700px){.quick-view-shell{padding:17px}.quick-view-content{padding-top:35px}.quick-view-product-card{grid-template-columns:1fr;gap:14px}.quick-view-product-card .product-card-media{height: min(42vh,320px);min-height:220px}.quick-view-product-card .product-card-body{padding:5px 0 8px}.quick-view-close{top:8px;right:8px;width:38px;height:38px}}
</style>
<script>
(()=>{if(window.__giftchetaQuickView)return;window.__giftchetaQuickView=true;let dialog=null;function getDialog(){if(dialog)return dialog;dialog=document.createElement('dialog');dialog.className='quick-view-dialog';dialog.setAttribute('aria-label','Бърз преглед на продукт');const shell=document.createElement('div');shell.className='quick-view-shell';const close=document.createElement('button');close.className='quick-view-close';close.type='button';close.setAttribute('aria-label','Затвори прегледа');close.dataset.quickViewClose='';close.textContent='×';const content=document.createElement('div');content.className='quick-view-content';shell.append(close,content);dialog.append(shell);dialog.addEventListener('click',event=>{if(event.target===dialog||event.target.closest('[data-quick-view-close]'))dialog.close();else if(event.target.closest('a'))event.preventDefault()});dialog.addEventListener('close',()=>{document.body.classList.remove('quick-view-open')});document.body.append(dialog);return dialog}document.addEventListener('click',event=>{const trigger=event.target.closest('[data-quick-view-trigger]');if(!trigger)return;const card=trigger.closest('.product-card');if(!card)return;event.preventDefault();const modal=getDialog(),content=modal.querySelector('.quick-view-content'),clone=card.cloneNode(true);clone.classList.add('quick-view-product-card');clone.querySelector('[data-quick-view-trigger]')?.remove();clone.querySelectorAll('.product-card-detail-meta').forEach(item=>item.style.display='block');content.replaceChildren(clone);document.body.classList.add('quick-view-open');modal.showModal()});window.addEventListener('cart:open',()=>{if(dialog?.open)dialog.close()});})();
</script>
